#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define REFERER_TOTAL_LEN 96U
#define MAX_SPRAY_ALLOCS 4096U

struct spray_hold {
  char **items;
  size_t count;
};

static size_t sink(char *ptr, size_t size, size_t nmemb, void *userdata)
{
  (void)ptr;
  (void)userdata;
  return size * nmemb;
